def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def clamp_move(dx, dy):
        if dx < -1:
            dx = -1
        elif dx > 1:
            dx = 1
        if dy < -1:
            dy = -1
        elif dy > 1:
            dy = 1
        return [dx, dy]

    def pos(obj, default=(0, 0)):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        return default

    def nearest(targets, x, y):
        best = None
        best_d = None
        for t in targets or []:
            tx, ty = pos(t, None)
            if tx is None:
                continue
            d = abs(tx - x) + abs(ty - y)
            if best is None or d < best_d:
                best = (tx, ty)
                best_d = d
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return clamp_move(sgn(ox - sx), sgn(oy - sy))

        corners = []
        if gw and gh:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        if corners:
            target = max(corners, key=lambda c: abs(c[0] - ox) + abs(c[1] - oy))
            return clamp_move(sgn(target[0] - sx), sgn(target[1] - sy))
        return clamp_move(-sgn(ox - sx), -sgn(oy - sy))

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        target = nearest(targets, sx, sy)
        if target is None:
            center = (gw // 2, gh // 2) if gw and gh else (sx, sy)
            target = center
        return clamp_move(sgn(target[0] - sx), sgn(target[1] - sy))

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = nearest(resources, sx, sy)
    if target is not None:
        return clamp_move(sgn(target[0] - sx), sgn(target[1] - sy))

    # Fallback: move away from opponent if threatened, else drift to center.
    if abs(ox - sx) + abs(oy - sy) <= 2:
        return clamp_move(-sgn(ox - sx), -sgn(oy - sy))
    if gw and gh:
        cx, cy = gw // 2, gh // 2
        return clamp_move(sgn(cx - sx), sgn(cy - sy))
    return [0, 0]

